pub fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let w: usize = width as usize;
    let n: usize = orig.len();

    // If no padding required, return the original unchanged.
    if n >= w {
        return orig;
    }

    let pad = w - n; // safe because n < w

    let mut res: Vec<char> = Vec::with_capacity(w);
    res.extend(std::iter::repeat(fillchar).take(pad));
    res.extend(orig);
    res
}

